//! ♻️ Public recursive receivers retain every cancelled prefix and exact serde output.
use super::*;
struct Bank{left:RetainedCloneGrant,work:u64}
impl Bank{fn new()->Self{let f:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&f["stock"];Self{left:RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize},work:s["fuel"].as_u64().unwrap()}}fn grant(&self)->RetainedCloneGrant{assert!(self.left.maximum_items>0&&self.work>0);RetainedCloneGrant{maximum_items:1,..self.left}}fn post(&mut self,p:RetainedCloneProgress,work:u64){assert!(p.fits(self.left));self.left.maximum_items-=p.copied_items;self.left.maximum_copy_bytes-=p.copied_bytes;self.left.maximum_capacity_bytes-=p.retained_capacity_bytes;self.left.maximum_release_bytes-=p.released_bytes;self.work=self.work.checked_sub(work).unwrap();}fn step(&mut self,turn:crate::RetainedWorkOutcome)->RetainedCloneStep{let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());self.post(p,turn.work);turn.result.unwrap()}fn retire<T:crate::retirement::RetireOwned>(&mut self,value:T){let mut retirement_actual=None;let mut retirement_work=0;let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();for _ in 0..10000{if owner.terminal_is_empty()&&retirement_actual.is_none(){return}let(result,heap)=observe(||{let turn=crate::source_fixture::close_step(&mut retirement_actual,self.grant(),self.work,owner.next_demand(4096),owner.next_computational_work(4096),|g,a|{let result=owner.step(g,a);crate::RetainedWorkOutcome{result,work:owner.last_turn_work()}});retirement_work=turn.work;turn.result});let work=retirement_work;let p=result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));self.step(crate::RetainedWorkOutcome{result,work});}panic!("recursive cursor fixture close depleted its unchanged finite stock")}}
fn observe<R>(f:impl FnOnce()->R)->(R,(usize,usize)){crate::observe_retirement_allocations(f)}
#[derive(crate::RetireOwned,crate::NativeReceive,serde::Serialize)]#[value(crate="crate",native_owned="crate")]struct RecursiveNode{children:Vec<RecursiveNode>}
#[derive(serde::Deserialize,serde::Serialize)]struct OracleNode{children:Vec<OracleNode>}
#[test]fn actual_recursive_native_receivers_keep_finite_headers_exact_serde_output_and_cancelled_custody(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let oracle:OracleNode=serde_json::from_value(f["input"].clone()).unwrap();assert_eq!(serde_json::to_value(oracle).unwrap(),f["input"]);for cut in std::iter::once(None).chain(f["cancelCuts"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()))){let mut bank=Bank::new();let source=crate::source_fixture::capture(crate::DslValue::from(&f["input"]),&mut bank,Bank::grant,|bank|bank.work,|bank,p,work,_,_|bank.post(p,work));let(mut receiver,heap)=observe(<RecursiveNode as NativeReceive<crate::DslValue>>::receiver);assert_eq!(heap,(0,0));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<24,&mut callback);let mut ready=false;for turn in 0..10000{if receiver.output_ready(){ready=true;break}if cut.is_some_and(|cut|turn>=cut){break}let g=bank.grant();let(result,heap)=observe(||crate::source_fixture::receive(&mut control,g,crate::source_fixture::WorkLoan::new(&bank.work,bank.work),|control|{let maximum=control.available_work_units().unwrap();receiver.advance(source.borrow(),control,4096,maximum,g)}));let p=result.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.post(p,result.work);result.result.unwrap();}if cut.is_none(){assert!(ready);let turn=receiver.take(bank.grant());let p=turn.result.as_ref().unwrap().as_ref().map(|(_,p)|*p).unwrap_or_default();bank.post(p,turn.work);let(value,_)=turn.result.unwrap().unwrap();assert_eq!(serde_json::to_value(&value).unwrap(),f["input"]);bank.retire(value);}receiver.begin_close().unwrap();let mut actual=None;for _ in 0..10000{if receiver.terminal_is_empty()&&actual.is_none(){break}let(result,heap)=observe(||crate::source_fixture::close_step(&mut actual,bank.grant(),bank.work,receiver.close_demands(4096),receiver.close_work_demand(4096),|g,a|receiver.close_step(g,a)));let p=result.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.step(result);}assert!(receiver.terminal_is_empty());assert_eq!(observe(||drop(receiver)).1,(0,0));bank.retire(source);}
}
